const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v+'T12:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'});
const pace=v=>Math.floor(Math.round(v)/60)+':'+String(Math.round(v)%60).padStart(2,'0');
export function patternMarkup(data,model){
 const weeks=model.effortWeeks,rated=weeks.reduce((n,w)=>n+w.rated,0),total=weeks.reduce((n,w)=>n+w.total,0),max=Math.max(1,...weeks.map(w=>w.load)),byId=new Map(model.sessions.map(s=>[s.id,s]));
 const groups=(data.routeMatches||[]).map(g=>g.sessionIds.map(id=>byId.get(id)).filter(s=>s&&s.paceSPerKm!==null).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))).filter(g=>g.length>=2);
 return `<section class="pp-section"><div class="pr-panel-head"><h2>How hard your weeks felt.</h2><span>${rated} of ${total} runs rated</span></div>${rated?`<div class="pp-load">${weeks.map(w=>`<div class="pp-load-row"><span>${date(w.start)}</span><div><i style="width:${w.load/max*100}%" aria-hidden="true"></i></div><strong>${w.rated?Math.round(w.load):'—'}</strong><small>${w.rated}/${w.total} rated</small></div>`).join('')}</div><details class="pr-values"><summary>What this shows</summary><p>Session load = running minutes × your reported effort, from one to ten. Weekly bars sum only rated runs. A dash means no rated run, not zero training. This is your session-RPE load, not Strava’s proprietary Relative Effort or a fitness score.</p></details>`:'<p class="pr-note">Log how a run felt to start seeing your weekly effort.</p><a class="pp-action" href="/training?view=sessions">Choose a run to rate</a>'}</section>${groups.length?`<section class="pp-section"><div class="pr-panel-head"><h2>Same route. A clearer comparison.</h2><span>${groups.length} ${groups.length===1?'route':'routes'}</span></div>${groups.slice(0,4).map(rows=>{const min=Math.min(...rows.map(s=>s.paceSPerKm))-15,max=Math.max(...rows.map(s=>s.paceSPerKm))+15,x=i=>55+i/(rows.length-1)*420,y=s=>20+(s.paceSPerKm-min)/(max-min)*95,best=rows.reduce((a,b)=>a.paceSPerKm<b.paceSPerKm?a:b);return `<article class="pp-route"><h3>${esc(rows.at(-1).title)}</h3><p>${rows.length} runs · best ${pace(best.paceSPerKm)} /km</p><svg viewBox="0 0 520 155" role="img" aria-label="Pace across matched runs in date order, faster is higher. Open View these runs for exact values and session links."><path class="pr-grid" d="M50 20H480M50 115H480"/><text x="0" y="25">${pace(min)}</text><text x="0" y="120">${pace(max)}</text><path class="pr-effort-line" d="${rows.map((s,i)=>`${i?'L':'M'}${x(i)},${y(s)}`).join(' ')}"/>${rows.map((s,i)=>`<circle cx="${x(i)}" cy="${y(s)}" r="5" class="pp-dot"><title>${date(s.date)} · ${pace(s.paceSPerKm)} /km</title></circle>`).join('')}<text x="55" y="148">${date(rows[0].date)}</text><text x="475" y="148" text-anchor="end">${date(rows.at(-1).date)}</text></svg><details class="pr-values"><summary>View these runs</summary>${rows.toReversed().map(s=>`<a class="pp-run" href="/app.html?activity=${encodeURIComponent(s.id)}"><span>${date(s.date)} · ${esc(s.title)}</span><strong>${pace(s.paceSPerKm)} /km</strong></a>`).join('')}<p>Matched from recorded GPS shape, direction, start/finish and distance. Timer pace. Points are sessions in date order.</p></details></article>`;}).join('')}</section>`:''}`;
}
